export const getZitadelGqlConfig = () => {
    const config = __JAEN_ZITADEL_GQL__;
    if (!config.organizationId) {
        throw new Error('jaen: zitadelGql.organizationId is required to use the Zitadel API. ' +
            'It is optional only for signing in, which is plain OIDC.');
    }
    return config;
};
export const getZitadelGqlUrl = () => {
    const config = getZitadelGqlConfig();
    return config.graphqlUrl || `${config.authority.replace(/\/+$/, '')}/graphql`;
};
export class ZitadelGqlError extends Error {
    constructor(message, errors = []) {
        super(message);
        this.errors = errors;
        this.name = 'ZitadelGqlError';
    }
}
export const zitadelGqlFetch = async (options) => {
    const response = await fetch(getZitadelGqlUrl(), {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            ...(options.accessToken
                ? { Authorization: `Bearer ${options.accessToken}` }
                : {})
        },
        body: JSON.stringify({
            query: options.query,
            variables: options.variables ?? {}
        })
    });
    if (!response.ok) {
        throw new ZitadelGqlError(`zitadel-gql request failed: HTTP ${response.status}`);
    }
    const payload = (await response.json());
    if (payload.errors && payload.errors.length > 0) {
        throw new ZitadelGqlError(payload.errors[0]?.message ?? 'zitadel-gql returned errors', payload.errors);
    }
    if (payload.data === undefined || payload.data === null) {
        throw new ZitadelGqlError('zitadel-gql returned no data');
    }
    return payload.data;
};
export const connectionNodes = (connection) => connection?.edges?.map(edge => edge.node) ?? [];
export const primaryProfile = (user) => connectionNodes(user.profiles)[0];
const USER_CORE_FIELDS = `
  id
  state
  userName
  loginNames
  preferredLoginName
`;
const HUMAN_DETAIL_FRAGMENT = `
  ... on HumanUser {
    preferences {
      preferredLanguage
    }
    profiles {
      edges {
        node {
          id
          email
          phone
          firstName
          lastName
          displayName
          avatarUrl
          preferredLanguage
        }
      }
    }
    roles {
      edges {
        node {
          key
          displayName
        }
      }
    }
    authorizations {
      edges {
        node {
          id
          projectId
          projectName
          roleKeys
          state
        }
      }
    }
  }
  ... on MachineUser {
    roles {
      edges {
        node {
          key
          displayName
        }
      }
    }
    authorizations {
      edges {
        node {
          id
          projectId
          projectName
          roleKeys
          state
        }
      }
    }
  }
`;
export const fetchCurrentUserRoles = async (accessToken) => {
    const data = await zitadelGqlFetch({
        query: `
      query JaenCurrentUserRoles {
        currentUser {
          id
          ... on HumanUser {
            roles { edges { node { key } } }
            authorizations { edges { node { id projectId projectName roleKeys state } } }
          }
          ... on MachineUser {
            roles { edges { node { key } } }
            authorizations { edges { node { id projectId projectName roleKeys state } } }
          }
        }
      }
    `,
        accessToken
    });
    const user = data.currentUser;
    const plainRoles = connectionNodes(user.roles).map(role => role.key);
    const projectScopedRoles = connectionNodes(user.authorizations).flatMap(authorization => authorization.roleKeys.map(roleKey => `${authorization.projectId}:${roleKey}`));
    return { plainRoles, projectScopedRoles };
};
export const fetchCurrentUser = async (accessToken) => {
    const data = await zitadelGqlFetch({
        query: `
      query JaenCurrentUser {
        currentUser {
          ${USER_CORE_FIELDS}
          resourceOwner
          creationDate
          changeDate
          ${HUMAN_DETAIL_FRAGMENT}
        }
      }
    `,
        accessToken
    });
    return data.currentUser;
};
export const fetchUsers = async (options) => {
    const data = await zitadelGqlFetch({
        query: `
      query JaenUsers($limit: Number) {
        users(args: {limit: $limit}) {
          totalCount
          edges {
            node {
              ${USER_CORE_FIELDS}
              ... on HumanUser {
                profiles {
                  edges {
                    node {
                      id
                      email
                      phone
                      firstName
                      lastName
                      displayName
                      avatarUrl
                      preferredLanguage
                    }
                  }
                }
              }
            }
          }
        }
      }
    `,
        variables: { limit: options.limit ?? 500 },
        accessToken: options.accessToken
    });
    return {
        totalCount: data.users.totalCount ?? data.users.edges.length,
        users: connectionNodes(data.users)
    };
};
